import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D7WGirly.js";const h=JSON.parse('{"title":"CLI","description":"The tuimark command-line interface, its commands, flags and exit codes.","frontmatter":{"title":"CLI","description":"The tuimark command-line interface, its commands, flags and exit codes.","editLink":false,"head":[["link",{"rel":"canonical","href":"https://tuimark.vercel.app/reference/cli"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Tuimark"}],["meta",{"property":"og:title","content":"CLI | Tuimark"}],["meta",{"property":"og:description","content":"The tuimark command-line interface, its commands, flags and exit codes."}],["meta",{"property":"og:url","content":"https://tuimark.vercel.app/reference/cli"}],["meta",{"name":"twitter:title","content":"CLI | Tuimark"}],["meta",{"name":"twitter:description","content":"The tuimark command-line interface, its commands, flags and exit codes."}]]},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1792236800000}'),d={name:"reference/cli.md"};function o(r,e,c,i,p,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tuimark — a view language for terminals</span></span>
<span class="line"><span></span></span>
<span class="line"><span>usage:</span></span>
<span class="line"><span>  tuimark dump     FILE [--cols 80] [--rows 24] [--format text|json] [--data FILE.json]</span></span>
<span class="line"><span>                        [--cells] [--styles] [--strict] [--theme dark|light]</span></span>
<span class="line"><span>  tuimark validate FILE [--json] [--strict] [--catalog FILE] [--data FILE.json] [--theme dark|light]</span></span>
<span class="line"><span>  tuimark preview  FILE [--cols 80] [--rows 24] [--data FILE.json] [--watch] [--theme dark|light]</span></span>
<span class="line"><span>                        [--color truecolor|256|16|none]</span></span>
<span class="line"><span>  tuimark play     FILE [--cols 80] [--rows 24] [--data FILE.json] [--theme dark|light]</span></span>
<span class="line"><span>                        [--input STEPS | --script FILE.ndjson]</span></span>
<span class="line"><span>                        [--format text|json] [--cells] [--styles] [--frames] [--strict]</span></span>
<span class="line"><span>  tuimark fmt      FILE [--write] [--check]</span></span>
<span class="line"><span>  tuimark ir       FILE                       print the source IR as JSON</span></span>
<span class="line"><span>  tuimark agents   [--repo | --project]       print AGENTS.md generated from the catalog</span></span>
<span class="line"><span>                                               (--project: the briefing tuimark new writes)</span></span>
<span class="line"><span>  tuimark catalog                             print the closed vocabulary as JSON</span></span>
<span class="line"><span>  tuimark new      NAME [--go | --ts]         create a project: app.tui, theme.tcss, sample.json, AGENTS.md</span></span>
<span class="line"><span>  tuimark test     [DIR] [--update] [--allow-breaking]</span></span>
<span class="line"><span>                                               check dump goldens under DIR (default testdata/golden)</span></span>
<span class="line"><span>  tuimark inspect  FILE (--at X,Y | --id ID) [--cols 80] [--rows 24] [--data FILE.json]</span></span>
<span class="line"><span>                        [--theme dark|light] [--strict] [--json]</span></span>
<span class="line"><span>                                               explain one node: path, classes, pseudo-classes, styles</span></span>
<span class="line"><span>  tuimark run      FILE [--data FILE.json] [--theme dark|light] [--events FILE.ndjson]</span></span>
<span class="line"><span>                        [--mock FILE.json] [--strip]</span></span>
<span class="line"><span>                                               run in the terminal: F12 shows the events, edits reload</span></span>
<span class="line"><span>  tuimark host     FILE [--data FILE.json] [--theme dark|light] [--reply-timeout 5s]</span></span>
<span class="line"><span>                                               run in the terminal for a parent program (fd 3 in, fd 4 out)</span></span>
<span class="line"><span>  tuimark mcp                                 a Model Context Protocol server on stdin/stdout</span></span>
<span class="line"><span>  tuimark lsp                                 a Language Server Protocol server on stdin/stdout</span></span>
<span class="line"><span>  tuimark version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>exit codes: 0 ok, 1 I/O or crash, 2 validation errors</span></span></code></pre></div><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>dump</code></td><td>Renders one frame: the grid, every node&#39;s geometry, and the diagnostics. Text by default, <code>--format json</code> for agents.</td><td><a href="/guide/tools#dump">Dumps and tools</a></td></tr><tr><td><code>validate</code></td><td>Checks a document without printing a frame. Lays it out at 40, 80, and 120 columns to find layout and bind problems.</td><td><a href="/guide/getting-started#check-it">Getting started</a></td></tr><tr><td><code>preview</code></td><td>The text dump, plus the frame painted in ANSI colors when stdout is a terminal. <code>--watch</code> re-renders on save.</td><td><a href="/guide/getting-started#look-at-it">Getting started</a></td></tr><tr><td><code>play</code></td><td>Replays keys, typing, pastes, clicks, and store changes with no terminal, and prints the final frame plus every action that fired.</td><td><a href="/guide/tools#play">Dumps and tools</a></td></tr><tr><td><code>inspect</code></td><td>Explains one cell or node: its layout path, classes, pseudo-classes, and which rule set each property.</td><td><a href="/guide/tools#inspect">Dumps and tools</a></td></tr><tr><td><code>fmt</code></td><td>The canonical formatter. <code>--check</code> exits 2 when a file is not formatted.</td><td><a href="/guide/tools#fmt">Dumps and tools</a></td></tr><tr><td><code>ir</code></td><td>Prints the parsed document as JSON, before the stylesheet cascade.</td><td><a href="/guide/tools#ir">Dumps and tools</a></td></tr><tr><td><code>test</code></td><td>Compares dumps with the goldens a manifest lists; <code>--update</code> rewrites them.</td><td><a href="/guide/testing#golden-dumps">Testing</a></td></tr><tr><td><code>agents</code></td><td>Prints the <code>AGENTS.md</code> briefing, generated from the runtime&#39;s own catalogs. <code>--project</code> prints the briefing <code>new</code> writes into a project.</td><td><a href="/guide/agents">Working with agents</a></td></tr><tr><td><code>catalog</code></td><td>Prints the closed vocabulary (tags, attributes, properties, keys, actions, diagnostic codes) as JSON, each item with the document version that accepts it.</td><td><a href="/guide/tools#catalog">Dumps and tools</a></td></tr><tr><td><code>new</code></td><td>Creates a project: <code>app.tui</code>, <code>theme.tcss</code>, <code>sample.json</code>, and <code>AGENTS.md</code>; <code>--go</code> or <code>--ts</code> adds the program that hosts it.</td><td><a href="/guide/tools#new">Dumps and tools</a></td></tr><tr><td><code>run</code></td><td>Runs a document in the terminal with no host program: an event strip (<code>F12</code>), an <code>--events</code> log, <code>--mock</code> store writes, and reload on save.</td><td><a href="/guide/run">Running a document</a></td></tr><tr><td><code>version</code></td><td>Prints the version.</td><td></td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>ok</td></tr><tr><td><code>1</code></td><td>usage error, I/O error, or crash; nothing useful on stdout</td></tr><tr><td><code>2</code></td><td>the document has an error-severity diagnostic (<code>dump</code>, <code>validate</code>, <code>play</code>, <code>inspect</code>, <code>ir</code>), a file is not formatted (<code>fmt --check</code>), or a golden does not match (<code>test</code>)</td></tr></tbody></table><p><code>run</code> exits <code>0</code> when the session quits or its input ends, and 128 + the signal number when a stop signal ends it.</p><p><code>--cols</code> and <code>--rows</code> take 1 to 1000. <code>dump</code>, <code>validate</code>, <code>play</code>, <code>inspect</code>, <code>ir</code>, <code>fmt</code>, and <code>test</code> never read <code>TUIMARK_*</code> environment variables, so their output never depends on the machine they run on.</p>`,8)])])}const u=t(d,[["render",o]]);export{h as __pageData,u as default};
